  "Reset it in the company app": "Libadilishe katika programu ya kampuni",
  "How LeMoSp works for a Small business": "Jinsi LeMoSp inavyofanya kazi kwa biashara Ndogo",
  "How LeMoSp works for a Medium business": "Jinsi LeMoSp inavyofanya kazi kwa biashara ya Kati",
  "How LeMoSp works for a Large (Enterprise) business": "Jinsi LeMoSp inavyofanya kazi kwa biashara Kubwa (Enterprise)",
  "The Small setup is for a new or small supplier: one shop or store, a few people and a few dozen customers. It keeps only the essentials: customers, stock, quotations, deliveries, invoices and payments. This quick guide shows them on the real screens.": "Mpangilio Mdogo ni kwa msambazaji mpya au mdogo: duka au stoo moja, watu wachache na wateja makumi kadhaa. Unahifadhi mambo muhimu tu: wateja, stoku, nukuu za bei, usafirishaji, ankara na malipo. Mwongozo huu mfupi unayaonyesha kwenye skrini halisi.",
  "The Medium setup is for a growing supplier with a team, corporate clients such as mines and factories, and several suppliers. On top of the essentials it adds approvals, supplier price comparison, credit limits, several stores, batches and expiry, and money owed both ways.": "Mpangilio wa Kati ni kwa msambazaji anayekua mwenye timu, wateja wa makampuni kama migodi na viwanda, na wasambazaji kadhaa. Juu ya mambo muhimu unaongeza idhini, ulinganisho wa bei za wasambazaji, kikomo cha mkopo, stoo kadhaa, bechi na tarehe za kuisha, na madeni ya pande zote mbili.",
  "The Large (Enterprise) setup is for a big supplier with stores in several regions, imports, departments and a large team. It adds group-wide reports, landed cost on imports, several currencies, a full activity log and strict security.": "Mpangilio Mkubwa (Enterprise) ni kwa msambazaji mkubwa mwenye stoo katika mikoa kadhaa, uagizaji kutoka nje, idara na timu kubwa. Unaongeza ripoti za kampuni nzima, gharama halisi za bidhaa za kuagiza, sarafu kadhaa, kumbukumbu kamili ya shughuli na usalama madhubuti.",
  "Owners who do most of the work themselves, with a small team.": "Wamiliki wanaofanya kazi nyingi wenyewe, wakiwa na timu ndogo.",
  "A team with sales, procurement, stores and finance people.": "Timu yenye watu wa mauzo, ununuzi, stoo na fedha.",
  "Directors, department heads and large teams.": "Wakurugenzi, wakuu wa idara na timu kubwa.",
  "You get organised in a day, without learning a big system.": "Unajipanga ndani ya siku moja, bila kujifunza mfumo mkubwa.",
  "Everyone works in one system, and managers stay in control without doing everything themselves.": "Kila mtu anafanya kazi katika mfumo mmoja, na mameneja wanabaki na udhibiti bila kufanya kila kitu wenyewe.",
  "Head office sees everything in one place, with the controls that auditors and big clients expect.": "Ofisi kuu inaona kila kitu mahali pamoja, ikiwa na udhibiti unaotarajiwa na wakaguzi na wateja wakubwa.",
  "That's the Small setup": "Huo ndio mpangilio Mdogo",
  "That's the Medium setup": "Huo ndio mpangilio wa Kati",
  "That's the Large (Enterprise) setup": "Huo ndio mpangilio Mkubwa (Enterprise)",
  "Customers, stock, quotations, deliveries, invoices and payments, all in one app on your phone. When the business grows, LeMoSp suggests the next tools, and nothing you entered is ever lost.": "Wateja, stoku, nukuu za bei, usafirishaji, ankara na malipo, vyote katika programu moja kwenye simu yako. Biashara ikikua, LeMoSp inapendekeza zana zinazofuata, na hakuna ulichoingiza kinachopotea.",
  "Requests become quotations and quotations become orders. Suppliers are compared, approvals keep spending and discounts under control, and stock, money owed and profit stay visible to managers.": "Maombi yanakuwa nukuu za bei na nukuu zinakuwa oda. Wasambazaji hulinganishwa, idhini hudhibiti matumizi na punguzo, na stoku, madeni na faida vinaonekana kwa mameneja.",
  "Many stores, imports, currencies and departments run from one control tower, with real profit figures, a full activity log and strong security. Any single feature can still be switched on or off.": "Stoo nyingi, uagizaji, sarafu na idara vinaendeshwa kutoka kituo kimoja cha udhibiti, vikiwa na takwimu halisi za faida, kumbukumbu kamili ya shughuli na usalama imara. Kipengele chochote bado kinaweza kuwashwa au kuzimwa.",
