  "Add costs": "Ongeza gharama",
  "Add feature": "Ongeza kipengele",
  "Add freight, duty, clearing and other costs to an order to see the true cost of imported goods.": "Ongeza usafirishaji, ushuru, uondoshaji na gharama nyingine kwenye oda ili kuona gharama halisi ya bidhaa zilizoagizwa kutoka nje.",
  "Add items and prices": "Ongeza bidhaa na bei",
  "Add items one by one or import a spreadsheet.": "Ongeza bidhaa moja moja au ingiza lahajedwali.",
  "Add products": "Ongeza bidhaa",
