  "Add the items": "Ongeza bidhaa",
  "Add vehicles": "Ongeza magari",
  "Add your company details and logo": "Ongeza taarifa za kampuni yako na nembo",
  "Add your first customers and products": "Ongeza wateja na bidhaa zako za kwanza",
  "Admin sections": "Sehemu za usimamizi",
  "Administration": "Usimamizi",
  "Advanced tools for growing sales, inventory, procurement, customers, and employees.": "Zana za hali ya juu za kukuza mauzo, stoku, ununuzi, wateja na wafanyakazi.",
  "Agree balances with customers and suppliers quickly.": "Kubaliana salio na wateja na wasambazaji haraka.",
  "Alerts & notifications": "Arifa na taarifa",
  "Alerts for new requests, approvals, overdue invoices, low stock and more, in the app, by push and by email.": "Arifa za maombi mapya, idhini, ankara zilizochelewa, stoku pungufu na zaidi, ndani ya programu, kwa push na kwa barua pepe.",
  "All levels": "Viwango vyote",
  "All staff, purchasing": "Wafanyakazi wote, ununuzi",
  "All suggestions from real companies, counted without names. Darker cells are the topics people raise most.": "Mapendekezo yote kutoka kwa kampuni halisi, yamehesabiwa bila majina. Visanduku vyenye rangi nzito ni mada zinazoibuliwa zaidi.",
  "Allow notifications when the app asks.": "Ruhusu arifa programu inapouliza.",
  "Always know which invoices are paid.": "Jua kila wakati ankara zipi zimelipwa.",
  "Always quote the agreed contract price and renew on time.": "Toa nukuu ya bei kwa bei ya mkataba iliyokubaliwa na uhuishe kwa wakati.",
  "An improvement task for the team. It is approved straight away and can be assigned to someone.": "Kazi ya uboreshaji kwa timu. Huidhinishwa mara moja na inaweza kukabidhiwa mtu.",
  "Analytics": "Uchambuzi",
  "Answer a few short questions and LeMoSp suggests the right starting level for your business.": "Jibu maswali machache mafupi na LeMoSp itapendekeza kiwango sahihi cha kuanzia kwa biashara yako.",
  "Anything else that would make us better.": "Jambo lingine lolote litakalotufanya tuwe bora zaidi.",
  "Approval workflows": "Mtiririko wa idhini",
  "Approve and order": "Idhinisha na uagize",
  "Approve in order": "Idhinisha kwa mpangilio",
  "Approve or return": "Idhinisha au rudisha",
  "Archive": "Hifadhi kumbukumbu",
  "Ask a question": "Uliza swali",
  "Ask for clarification": "Omba ufafanuzi",
  "Ask questions about your business in plain language and get drafts of quotations and emails.": "Uliza maswali kuhusu biashara yako kwa lugha rahisi na upate rasimu za nukuu za bei na barua pepe.",
  "Ask several suppliers for prices and compare their offers side by side.": "Omba bei kwa wasambazaji kadhaa na ulinganishe ofa zao kando kwa kando.",
  "Ask suppliers": "Uliza wasambazaji",
  "Ask suppliers for prices and compare them": "Omba bei kwa wasambazaji na uzilinganishe",
