  "Assign a driver and vehicle.": "Mpangie dereva na gari.",
  "Assign the delivery to the driver.": "Mkabidhi dereva uwasilishaji.",
  "Assign to (optional)": "Mkabidhi (si lazima)",
  "Assign to…": "Mkabidhi…",
  "Assigned": "Imekabidhiwa",
  "Assigned to me": "Nimekabidhiwa",
  "Attach documents and track progress.": "Ambatisha nyaraka na ufuatilie maendeleo.",
  "Attach the receipt": "Ambatisha risiti",
  "Availability": "Upatikanaji",
  "Available in Enterprise Mode": "Inapatikana katika Hali ya Kubwa",
  "Available in Medium Mode": "Inapatikana katika Hali ya Kati",
  "Available — switched off": "Inapatikana — imezimwa",
  "Average sales per month (TZS)": "Wastani wa mauzo kwa mwezi (TZS)",
  "Avoid running out, reduce old or slow-moving stock.": "Epuka kuishiwa, punguza stoku ya zamani au inayouzika polepole.",
  "Back": "Rudi",
  "Back to the dashboard": "Rudi kwenye dashibodi",
  "Bank & mobile-money reconciliation": "Ulinganisho wa benki na pesa za simu",
