  "Based on your recent activity, you may benefit from 1 {level} feature.": "Kulingana na shughuli zako za hivi karibuni, unaweza kunufaika na kipengele 1 cha {level}.",
  "Based on your recent activity, you may benefit from {n} more features.": "Kulingana na shughuli zako za hivi karibuni, unaweza kunufaika na vipengele {n} zaidi.",
