  "Benefit": "Faida",
  "Better tools, phones, internet or use of this app.": "Zana bora, simu, intaneti au matumizi ya programu hii.",
  "Big or risky deals are always checked before they go out.": "Mikataba mikubwa au yenye hatari hukaguliwa kila mara kabla ya kutumwa.",
  "Bills are listed by supplier and due date.": "Bili zimeorodheshwa kwa msambazaji na tarehe ya kulipa.",
