  "Driver app": "Programu ya dereva",
  "Driver app & proof of delivery": "Programu ya dereva na uthibitisho wa uwasilishaji",
  "Drivers see their deliveries on the phone and capture signature, photo and location, even offline.": "Madereva huona uwasilishaji wao kwenye simu na kunasa sahihi, picha na mahali, hata bila mtandao.",
  "Drivers, stores staff": "Madereva, wafanyakazi wa ghala",
  "Each approver is notified in turn.": "Kila mwidhinishaji hupewa arifa kwa zamu.",
  "Each branch is managed on its own while head office sees everything.": "Kila tawi husimamiwa peke yake huku ofisi kuu ikiona kila kitu.",
  "Each entry shows what changed from and to.": "Kila ingizo linaonyesha kilichobadilika kutoka nini kwenda nini.",
  "Each feature has a default level. Companies at that level or higher get it automatically; others can switch it on. Planned features are shown as “coming soon”.": "Kila kipengele kina kiwango chake cha msingi. Kampuni za kiwango hicho au zaidi hukipata kiotomatiki; nyingine zinaweza kukiwasha. Vipengele vilivyopangwa vinaonyeshwa kama “vinakuja hivi karibuni”.",
  "Each number opens the list behind it.": "Kila namba hufungua orodha iliyo nyuma yake.",
  "Each person sees only what they need for their work.": "Kila mtu huona tu anachohitaji kwa kazi yake.",
  "Employees": "Wafanyakazi",
  "Enter a threshold (a number, 0 or more).": "Weka kiwango cha kuanzia (namba, 0 au zaidi).",
  "Enter data once and share it with your other systems.": "Ingiza data mara moja na uishiriki na mifumo yako mingine.",
