  "Enterprise": "Kubwa",
  "Enterprise level": "Kiwango Kubwa",
  "Enterprise level features": "Vipengele vya kiwango Kubwa",
  "Essential tools for starting and organizing the business.": "Zana muhimu za kuanzisha na kupanga biashara.",
  "Every day the app measures each company (team size, products, stores, sales and more). When a measured number passes a rule's threshold, and the company is at one of the rule's levels, the owner gets a recommendation with the message below — either to switch on a feature or to move up a level. Owners can accept, postpone or dismiss it. Features already on, and levels already reached, are skipped.": "Kila siku programu hupima kila kampuni (ukubwa wa timu, bidhaa, maghala, mauzo na zaidi). Namba iliyopimwa inapovuka kiwango cha kuanzia cha kanuni, na kampuni iko kwenye mojawapo ya viwango vya kanuni, mmiliki hupata pendekezo la ukuaji lenye ujumbe ulio hapa chini — ama kuwasha kipengele au kupanda kiwango. Wamiliki wanaweza kukubali, kuahirisha au kulikataa. Vipengele vilivyowashwa tayari, na viwango vilivyofikiwa tayari, huachwa.",
  "Every foreign-currency document keeps the rate used, so figures add up.": "Kila hati ya sarafu ya kigeni huhifadhi kiwango kilichotumika, ili hesabu ziwiane.",
  "Every purchase starts from an approved need.": "Kila ununuzi huanza na hitaji lililoidhinishwa.",
  "Every team member can suggest improvements; management reviews, assigns and tracks them.": "Kila mwanatimu anaweza kupendekeza maboresho; uongozi huyapitia, huyagawa na kuyafuatilia.",
  "Every tutorial step needs a title.": "Kila hatua ya mafunzo inahitaji kichwa.",
  "Everyone": "Kila mtu",
  "Everything in Medium": "Kila kitu cha Kati",
  "Everything in Small": "Kila kitu cha Ndogo",
  "Expenses": "Matumizi",
  "Explain the reason in simple words. {value} is replaced by the company's number and {threshold} by the rule's threshold, e.g. “Your catalogue has grown to {value} products.”": "Eleza sababu kwa maneno rahisi. {value} hubadilishwa na namba ya kampuni na {threshold} na kiwango cha kuanzia cha kanuni, mfano “Katalogi yako imekua hadi bidhaa {value}.”",
