  "The dashboard is the first screen you see.": "Dashibodi ni skrini ya kwanza unayoiona.",
  "The demo opens a sample company next to yours, full of made-up data. For now all three buttons open the same demo: a medium-sized supplier. Separate Small and Enterprise demos are coming soon. Leave the demo to come back here.": "Onyesho linafungua kampuni ya mfano kando ya yako, yenye data za kubuni. Kwa sasa vitufe vyote vitatu vinafungua onyesho lilelile: msambazaji wa ukubwa wa kati. Maonyesho tofauti ya Ndogo na Kubwa yanakuja hivi karibuni. Toka kwenye onyesho kurudi hapa.",
  "The description is too long (600 letters at most).": "Maelezo ni marefu mno (herufi 600 zaidi).",
  "The details are too long (4,000 letters at most).": "Maelezo ni marefu mno (herufi 4,000 zaidi).",
  "The driver captures name, signature and photo.": "Dereva anachukua jina, sahihi na picha.",
  "The key must be lower-case letters, numbers and _ (e.g. many_products).": "Ufunguo lazima uwe herufi ndogo, namba na _ (mf. many_products).",
  "The key must be lower-case letters, numbers and _ (e.g. stock_transfers).": "Ufunguo lazima uwe herufi ndogo, namba na _ (mf. stock_transfers).",
  "The level is not a judgement of your company. It only sets which tools you see first.": "Kiwango si tathmini ya kampuni yako. Kinaamua tu zana unazoona kwanza.",
  "The level only decides which tools you see first. You can change it at any time, and you never lose any data.": "Kiwango kinaamua tu zana unazoona kwanza. Unaweza kukibadilisha wakati wowote, na hupotezi data yoyote.",
  "The level sets the default set of features. Changing it never deletes data, and features switched on or off individually keep their setting.": "Kiwango kinaweka vipengele vya msingi. Kukibadilisha hakufuti data, na vipengele vilivyowashwa au kuzimwa kimoja kimoja vinabaki na mpangilio wake.",
  "The level sets which tools you see first. It is not a judgement of your company, and changing it never deletes data.": "Kiwango kinaamua zana unazoona kwanza. Si tathmini ya kampuni yako, na kukibadilisha hakufuti data.",
  "The message is too long (500 letters at most).": "Ujumbe ni mrefu mno (herufi 500 zaidi).",
