  "Reset": "Weka upya",
  "Reset is for a lost or replaced phone: the person sets up the app again at their next sign-in.": "Kuweka upya ni kwa simu iliyopotea au kubadilishwa: mtu huyo ataweka programu tena atakapoingia.",
  "must enter a code from an authenticator app after their password. The database itself refuses access without it, so once someone has set up their app, a stolen password is not enough.": "lazima aandike namba kutoka kwenye programu ya uthibitishaji baada ya nenosiri. Hifadhidata yenyewe inakataa bila hiyo, kwa hiyo mtu akishaweka programu yake, nenosiri lililoibiwa halitoshi.",
