  "From then on, signing in asks for your password and a fresh code from the app.": "Kuanzia hapo, kuingia kutaomba nenosiri lako na namba mpya kutoka kwenye programu.",
  "Install an authenticator app on your phone, e.g. Google Authenticator or Microsoft Authenticator.": "Sakinisha programu ya uthibitishaji kwenye simu yako, mf. Google Authenticator au Microsoft Authenticator.",
