  "Signs people out when the app is left open without use, e.g. on a shared office computer. A warning appears a minute before. The driver screen is not affected, so deliveries can be recorded offline.": "Huwatoa watu programu ikiachwa wazi bila kutumika, mf. kwenye kompyuta ya ofisi ya pamoja. Onyo huonekana dakika moja kabla. Skrini ya dereva haiguswi, ili uwasilishaji urekodiwe hata bila mtandao.",
