  ", add": ", ongeza",
  ", add and verify your domain (triumphsuppliers.co.tz), create an API key, and add to Netlify:": ", ongeza na uthibitishe kikoa chako (triumphsuppliers.co.tz), unda ufunguo wa API, na uongeze kwenye Netlify:",
  ", open it from there, then come back to this page.": ", ifungue kutoka hapo, kisha urudi kwenye ukurasa huu.",
  ", row": ", safu",
  ", run this once (you can use the random text below, or your own of 24+ characters):": ", endesha hii mara moja (unaweza kutumia maandishi nasibu hapa chini, au yako mwenyewe ya herufi 24+):",
  ". Check the spelling against the Suppliers tab, or set it on each product.": ". Linganisha tahajia na kichupo cha Wasambazaji, au iweke kwenye kila bidhaa.",
  ". Cost of goods uses each product's cost when the invoice was issued (landed cost if it was applied). Freight, duty and clearing on purchase orders are part of the landed cost; transport, bank charges and similar costs are added on the order.": ". Gharama ya bidhaa hutumia gharama ya kila bidhaa wakati ankara ilipotolewa (gharama halisi ya kufikisha kama ilitumika). Usafirishaji, ushuru na uondoshaji kwenye oda za ununuzi ni sehemu ya gharama halisi ya kufikisha; usafiri, ada za benki na gharama nyingine zinaongezwa kwenye oda.",
  ". Generate a pair here (it is not saved anywhere — copy both straight into Netlify, keep the private one secret):": ". Tengeneza jozi hapa (haihifadhiwi popote — nakili zote mbili moja kwa moja kwenye Netlify, weka ule wa siri kuwa siri):",
  ". Green = cheapest. Totals include freight; a supplier that didn't price every item shows how many it priced.": ". Kijani = bei nafuu zaidi. Jumla zinajumuisha usafirishaji; msambazaji ambaye hakuweka bei kwa kila bidhaa anaonyesha ameweka bei ngapi.",
  ". On iPhone the app must first be added to the Home Screen.": ". Kwenye iPhone programu lazima kwanza iongezwe kwenye Skrini ya Mwanzo.",
  ". Record payments on the invoice they pay.": ". Rekodi malipo kwenye ankara inayolipwa.",
  ". Rows without an ID get one automatically. If anything fails, nothing is saved.": ". Safu zisizo na ID zinapewa moja moja kwa moja. Kitu chochote kikishindikana, hakuna kinachohifadhiwa.",
  ". Search to narrow the list.": ". Tafuta ili kupunguza orodha.",
