  "Nothing in stock here yet. Stock arrives when you receive goods against a purchase order, or through an adjustment (opening balance).": "Bado hakuna stoku hapa. Stoku huingia unapopokea bidhaa dhidi ya oda ya ununuzi, au kupitia marekebisho (salio la mwanzo).",
