  "Nothing waiting. New client requests will appear here.": "Hakuna kinachosubiri. Maombi mapya ya wateja yataonekana hapa.",
  "Nothing yet. You'll be told here when something needs you: approvals, new RFQs, deliveries, overdue invoices, stock alerts.": "Bado hakuna kitu. Utaarifiwa hapa kitu kikihitaji hatua yako: idhini, RFQ mpya, uwasilishaji, ankara zilizochelewa, arifa za stoku.",
  "Notifications": "Arifa",
  "Notifications always appear in the app (the bell at the top). This page connects the extras: phone notifications and alert emails, and the background job that checks for overdue invoices, expiring stock and so on every 5 minutes.": "Arifa huonekana kila mara kwenye programu (kengele juu). Ukurasa huu unaunganisha ziada: arifa za simu na barua pepe za arifa, pamoja na kazi ya nyuma inayokagua ankara zilizochelewa, stoku inayokwisha muda na mengineyo kila dakika 5.",
  "Notifications are blocked for this site. Allow them in your browser or phone settings, then reload.": "Arifa zimezuiwa kwa tovuti hii. Ziruhusu kwenye mipangilio ya kivinjari au simu yako, kisha pakia upya.",
  "Notifications are not switched on yet. Management needs to run the Stage 7 database update.": "Arifa bado hazijawashwa. Uongozi unahitaji kuendesha sasisho la hifadhidata la Hatua ya 7.",
  "Offer valid until": "Ofa ni halali hadi",
