  "The amounts are filled in from the purchase order — change them to match the invoice.": "Kiasi kimejazwa kutoka kwenye oda ya ununuzi — kibadilishe kilingane na ankara.",
  "The app couldn't read your company from the database.": "Programu imeshindwa kusoma kampuni yako kutoka kwenye hifadhidata.",
  "The bell tells you when quotations are about to expire, when goods arrive and when the client pays.": "Kengele inakujulisha nukuu za bei zinapokaribia kuisha muda, bidhaa zinapofika na mteja anapolipa.",
  "The bell warns you when an expected delivery date passes, and when stock falls below the reorder level.": "Kengele inakuonya tarehe ya uwasilishaji inayotarajiwa inapopita, na stoku inaposhuka chini ya kiwango cha kuagiza tena.",
  "The client accepted. Ask suppliers for prices, or order directly.": "Mteja amekubali. Omba bei kwa wasambazaji, au agiza moja kwa moja.",
  "The control tower shows what is critical, what needs attention and what is in progress. Every line opens the list behind it.": "Mnara wa udhibiti unaonyesha yaliyo hatari, yanayohitaji uangalizi na yanayoendelea. Kila mstari unafungua orodha iliyo nyuma yake.",
  "The database isn't set up yet": "Hifadhidata bado haijasanidiwa",
  "The database refused the request": "Hifadhidata imekataa ombi",
  "The landed cost can be applied once the supplier has confirmed the order.": "Gharama halisi ya kufikisha inaweza kutumika msambazaji akishathibitisha oda.",
  "The page could not load. Check your internet connection and try again. If it keeps happening, send this reference to support:": "Ukurasa umeshindwa kufunguka. Angalia muunganisho wa intaneti na ujaribu tena. Ikiendelea kutokea, tuma kumbukumbu hii kwa msaada:",
  "The whole flow: client RFQ → quotation → approval → order won → supplier quotes → purchase order → goods received → delivery → proof of delivery → invoice → payment → profit. Each person does their part and the next person is told.": "Mtiririko mzima: RFQ ya mteja → nukuu ya bei → idhini → oda imepatikana → bei za wasambazaji → oda ya ununuzi → bidhaa zimepokelewa → uwasilishaji → uthibitisho wa uwasilishaji → ankara → malipo → faida. Kila mtu anafanya sehemu yake na anayefuata anaarifiwa.",
  "Their email": "Barua pepe yao",
  "Their offer": "Ofa yao",
  "Their order / confirmation no.": "Namba yao ya oda / uthibitisho",
  "Their quote reference": "Kumbukumbu ya nukuu yao",
  "Then in": "Kisha katika",
  "Then reload this app.": "Kisha pakia upya programu hii.",
  "These “Main supplier” names didn't match any supplier, so those products have no main supplier yet:": "Majina haya ya “Msambazaji mkuu” hayakulingana na msambazaji yeyote, kwa hiyo bidhaa hizo bado hazina msambazaji mkuu:",
  "This bill has payments, so it can no longer be changed.": "Bili hii ina malipo, kwa hiyo haiwezi kubadilishwa tena.",
  "This browser cannot receive notifications. Try Chrome on Android, or Safari on iPhone.": "Kivinjari hiki hakiwezi kupokea arifa. Jaribu Chrome kwenye Android, au Safari kwenye iPhone.",
  "This device": "Kifaa hiki",
  "Tip: to buy for a client order, open the accepted quotation (or the client RFQ) and use “Request supplier quotes” so the items are copied across.": "Kidokezo: kununua kwa ajili ya oda ya mteja, fungua nukuu ya bei iliyokubaliwa (au RFQ ya mteja) na utumie “Omba bei kwa wasambazaji” ili bidhaa zinakiliwe.",
  "Tips": "Vidokezo",
  "Title": "Kichwa",
  "To compare several suppliers first, use a": "Kulinganisha wasambazaji kadhaa kwanza, tumia",
  "To deliver": "Za kuwasilisha",
  "To deliver a won order, open the accepted quotation and use “Create delivery note”: the items are copied, and later deliveries only include what is still outstanding.": "Kuwasilisha oda iliyopatikana, fungua nukuu ya bei iliyokubaliwa na utumie “Tengeneza hati ya uwasilishaji”: bidhaa zinakiliwa, na uwasilishaji unaofuata unajumuisha kilichobaki tu.",
  "To do": "Za kufanya",
  "To invoice a whole order (for example an advance payment invoice), open the accepted quotation and use “Create invoice”.": "Kutoa ankara ya oda nzima (kwa mfano ankara ya malipo ya awali), fungua nukuu ya bei iliyokubaliwa na utumie “Tengeneza ankara”.",
  "To pay": "Za kulipa",
  "To pay within 7 days (or late)": "Za kulipa ndani ya siku 7 (au zilizochelewa)",
