  "Type the prices exactly as the supplier quoted them, in their currency. Leave an item empty if they can't supply it.": "Andika bei kama msambazaji alivyozinukuu, kwa sarafu yao. Acha bidhaa wazi kama hawawezi kuisambaza.",
