  "Unpaid": "Haijalipwa",
  "Unpaid invoices by client and how late they are. Foreign-currency invoices are shown in": "Ankara zisizolipwa kwa kila mteja na zimechelewa kiasi gani. Ankara za fedha za kigeni zinaonyeshwa kwa",
  "Unpaid supplier bills. Totals are converted to": "Bili za wasambazaji zisizolipwa. Jumla zimebadilishwa kuwa",
  "Update": "Sasisha",
  "Update rates when the bank rate moves.": "Sasisha viwango benki inapobadilisha kiwango.",
  "Updated": "Imesasishwa",
  "Updates each product's cost, so quotation margins and profit use the real cost.": "Inasasisha gharama ya kila bidhaa, ili faida za nukuu za bei zitumie gharama halisi.",
  "Upload logo": "Pakia nembo",
  "Upload your logo and set your colours": "Pakia nembo yako na uweke rangi zako",
  "Urgent": "Haraka",
  "Use landed cost as product cost": "Tumia gharama hadi ghalani kama gharama ya bidhaa",
  "Use this for opening balances when you start, after a stock count, or to write off damaged or expired goods. Every adjustment is recorded with your name and reason.": "Tumia hii kwa salio la mwanzo unapoanza, baada ya kuhesabu stoku, au kufuta bidhaa zilizoharibika au zilizokwisha muda. Kila marekebisho yanarekodiwa pamoja na jina lako na sababu.",
  "Use this once at go-live to record what is physically in your stores. Count first, then fill in the template: one row per product, store and batch. If any row has a problem, nothing is loaded and you are told which rows to fix. Each row is recorded as an “Opening stock” adjustment.": "Tumia hii mara moja wakati wa kuanza kurekodi kilichopo kwenye maghala yako. Hesabu kwanza, kisha jaza kiolezo: mstari mmoja kwa kila bidhaa, ghala na bechi. Mstari wowote ukiwa na tatizo, hakuna kinachopakiwa na unaambiwa mistari ipi urekebishe. Kila mstari unarekodiwa kama marekebisho ya “Stoku ya mwanzo”.",
  "Used in the app and on your documents.": "Inatumika kwenye programu na kwenye nyaraka zako.",
  "Usually you invoice each delivery from its delivery note. Use this for advance or whole-order invoices.": "Kwa kawaida unatoa ankara kwa kila uwasilishaji kutoka kwenye hati yake ya uwasilishaji. Tumia hii kwa ankara za malipo ya awali au za oda nzima.",
