  "When": "Lini",
  "When a client asks for prices (email, phone, WhatsApp, visit), create a client RFQ with the items and due date. You get a reminder when it is due.": "Mteja anapoomba bei (barua pepe, simu, WhatsApp, ziara), tengeneza RFQ ya mteja yenye bidhaa na tarehe ya mwisho. Utapata kikumbusho ikifika.",
  "When the client replies, press Client accepted (add their PO number) or Client declined. Accepted orders go to procurement automatically.": "Mteja akijibu, bonyeza Mteja amekubali (ongeza namba yao ya PO) au Mteja amekataa. Oda zilizokubaliwa zinaenda kwa ununuzi moja kwa moja.",
  "When you submit, the app checks the margin and value. If they're within the rules it's approved straight away; otherwise management is asked to approve.": "Ukiwasilisha, programu inakagua faida na thamani. Zikiwa ndani ya kanuni inaidhinishwa papo hapo; vinginevyo menejimenti inaombwa kuidhinisha.",
  "Where": "Wapi",
  "Whole-order profit, including freight and other costs →": "Faida ya oda nzima, ikijumuisha usafirishaji na gharama nyingine →",
  "Won": "Imepatikana",
  "Won orders": "Oda zilizopatikana",
  "Won orders to buy for": "Oda zilizopatikana za kununulia",
  "Working…": "Inafanya kazi…",
  "Yes": "Ndiyo",
  "You": "Wewe",
  "You are told when a delivery is completed. Open it and press Create invoice, check it, then Issue invoice and share the PDF.": "Unaarifiwa uwasilishaji unapokamilika. Ufungue na ubonyeze Tengeneza ankara, ikague, kisha Toa ankara na ushiriki PDF.",
  "You are told when an order is won. Open it and press Request supplier quotes, or Create purchase order if you already know the supplier.": "Unaarifiwa oda inapopatikana. Ifungue na ubonyeze Omba bei kwa wasambazaji, au Tengeneza oda ya ununuzi kama tayari unamjua msambazaji.",
  "You buy the goods at the best price and make sure they arrive on time.": "Unanunua bidhaa kwa bei nzuri zaidi na kuhakikisha zinafika kwa wakati.",
  "You can": "Unaweza",
  "You can add the supplier and cost after saving.": "Unaweza kuongeza msambazaji na gharama baada ya kuhifadhi.",
  "You can ask suppliers for prices already.": "Unaweza tayari kuomba bei kwa wasambazaji.",
  "You deliver the goods and record proof of delivery on your phone.": "Unawasilisha bidhaa na kurekodi uthibitisho wa uwasilishaji kwenye simu yako.",
  "You invoice, collect money, pay suppliers and watch profit.": "Unatoa ankara, unakusanya fedha, unalipa wasambazaji na kufuatilia faida.",
  "You receive goods, keep stock right, and send deliveries out.": "Unapokea bidhaa, unaweka stoku sahihi, na unatuma uwasilishaji.",
  "You see everything, approve, and keep the system set up.": "Unaona kila kitu, unaidhinisha, na unasimamia mipangilio ya mfumo.",
  "You signed in successfully, but the app's tables aren't in the database yet. An administrator needs to run the setup file once in Supabase:": "Umeingia kwa mafanikio, lakini majedwali ya programu bado hayapo kwenye hifadhidata. Msimamizi anahitaji kuendesha faili la usanidi mara moja kwenye Supabase:",
  "You turn client requests into won orders.": "Unageuza maombi ya wateja kuwa oda zilizopatikana.",
  "You'll be its first manager and can invite your team afterwards. If your company already uses this app, ask a manager to invite": "Utakuwa meneja wake wa kwanza na unaweza kualika timu yako baadaye. Kama kampuni yako tayari inatumia programu hii, muombe meneja akualike",
  "You're signed in. Choose a new password below.": "Umeingia. Chagua nenosiri jipya hapa chini.",
  "You've been invited": "Umealikwa",
  "Your account": "Akaunti yako",
  "Your alerts, phone notifications and emails": "Tahadhari zako, arifa za simu na barua pepe",
  "Your companies": "Kampuni zako",
  "Your data": "Data yako",
  "Your data belongs to you. Download it any time, as a backup or to move to other software. CSV files open in Excel. The JSON file contains everything in one file. Signatures, photos and logos are not included (they stay in file storage).": "Data yako ni mali yako. Ipakue wakati wowote, kama nakala ya akiba au kuihamishia programu nyingine. Faili za CSV zinafunguka kwenye Excel. Faili la JSON lina kila kitu katika faili moja. Saini, picha na nembo hazijumuishwi (zinabaki kwenye hifadhi ya faili).",
