  "automatic checks done. Items marked • can't be checked from inside the app — follow the go-live runbook (GO-LIVE.md in the project) for those.": "ukaguzi wa kiotomatiki umefanyika. Vipengele vilivyowekwa alama • haviwezi kukaguliwa ndani ya programu — fuata mwongozo wa kuanza (GO-LIVE.md kwenye mradi) kwa hivyo.",
