  "for 1 unit of each currency. Quotations, purchase orders, invoices, bills and costs in a foreign currency take this rate automatically, and can only differ from it by up to 10%. This keeps approval limits, credit limits and margins honest.": "kwa kipimo 1 cha kila sarafu. Nukuu za bei, oda za ununuzi, ankara, bili na gharama kwa fedha za kigeni zinachukua kiwango hiki moja kwa moja, na zinaweza kutofautiana nacho kwa hadi 10% tu. Hii inaweka mipaka ya idhini, mipaka ya mkopo na faida kuwa za kweli.",
