  "Expense categories": "Makundi ya matumizi",
  "Rename the categories to match how you think about your spending. A category that is switched off is hidden when recording new expenses; old expenses keep it.": "Badilisha majina ya makundi yalingane na jinsi unavyofikiria matumizi yako. Kundi lililozimwa linafichwa wakati wa kurekodi matumizi mapya; matumizi ya zamani yanalibakiza.",
