  "Download as PDF or Excel in Reports →": "Pakua kama PDF au Excel kwenye Ripoti →",
  "A simple view for running the business, not a tax return. Sales are issued invoices by invoice date; expenses are counted on the date paid, without VAT. Supplier bills for stock are not expenses: their cost counts when the goods are sold. Freight, duty and clearing on purchase orders are part of the landed cost.": "Muhtasari rahisi wa kuendesha biashara, si ritani ya kodi. Mauzo ni ankara zilizotolewa kwa tarehe ya ankara; matumizi yanahesabiwa siku yaliyolipwa, bila VAT. Bili za wasambazaji za bidhaa za stoku si matumizi: gharama yake inahesabiwa bidhaa zinapouzwa. Usafirishaji, ushuru na uondoaji kwenye oda za manunuzi ni sehemu ya gharama halisi ya bidhaa.",
  "The file is too big. Use one month at a time.": "Faili ni kubwa mno. Tumia mwezi mmoja kwa wakati.",
  "Statement": "Taarifa",
  "Paste the statement here: select all in the M-Pesa / bank statement and copy, or load a CSV file.": "Bandika taarifa hapa: chagua yote kwenye taarifa ya M-Pesa / benki na unakili, au pakia faili la CSV.",
